function handler(params) {
  const sop = {
    '账号访问': '账号访问诊断：1.记录登录错误和发生时间；2.通过企业官方自助入口申请密码重置；3.如提示锁定，联系IT核验身份后解锁。不要发送密码或验证码。当前未执行账号变更。',
    'VPN网络': 'VPN诊断：1.确认普通网页可以访问；2.记录VPN客户端版本和报错；3.检查企业官方VPN配置；4.仍失败则向IT提供脱敏日志。不要关闭安全软件或提供密码。',
    '权限申请': '权限申请：1.说明目标系统和业务用途；2.确认需要的最小权限及期限；3.由负责人审批并由IT实施。当前未创建工单或授予权限。',
    '多诉求澄清': '你提出了多个独立事项，请先选择账号访问、VPN网络或权限申请中的一项，我将逐项处理。',
    '其他意图': '暂不能匹配已配置的IT服务，请说明目标系统、报错和期望结果，或联系人工IT服务台。'
  };
  return {key0: sop[params.input] || sop['其他意图'],
          key1: params.input, key2: [], key3: {}, key4: []};
}
